using System;using System.IO;using System.Linq;using System.Drawing;using System.Security.Cryptography;using System.Text;
namespace PZ3D {static class LauncherPictures {
 static object Empty(string message){return new{dataUrl=(string)null,mime=(string)null,message=message};}
 static object Read(string folder){string file=Path.Combine(folder,"thumb.png");LauncherMaintenance.NoReparse(file);if(!File.Exists(file))return Empty("尚无原版存档截图。");try{if(new FileInfo(file).Length>512*1024)return Empty("原版截图超过显示容量限制。");byte[] bytes=File.ReadAllBytes(file);byte[] magic={137,80,78,71,13,10,26,10};if(bytes.Length<24||!bytes.Take(8).SequenceEqual(magic))return Empty("原版截图格式无效。");long width=Big(bytes,16),height=Big(bytes,20);if(width<1||height<1||width>8192||height>8192||width*height>16777216)return Empty("原版截图尺寸超出限制。");using(var stream=new MemoryStream(bytes))using(var image=Image.FromStream(stream,true,true)){if(image.Width!=width||image.Height!=height)return Empty("原版截图尺寸不一致。");}return new{dataUrl="data:image/png;base64,"+Convert.ToBase64String(bytes),mime="image/png",message="原版最后保存的截图"};}catch{return Empty("原版截图当前不可读取。");}}
 static long Big(byte[] bytes,int offset){return ((long)bytes[offset]<<24)|((long)bytes[offset+1]<<16)|((long)bytes[offset+2]<<8)|bytes[offset+3];}
 public static object Save(Engine e,string id){return Read(SaveProfiles.ResolveSave(e,id));}
 public static object Server(Engine e,ServerLaunchTarget target){if(target==null||string.IsNullOrEmpty(target.Host)||string.IsNullOrEmpty(target.Username))return Empty("需要服务器地址、端口和角色账号才能匹配截图。");string role;using(var h=MD5.Create())role=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(target.Username))).Replace("-","").ToLowerInvariant();string name=target.Host+"_"+target.Port+"_"+role;if(name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||name.Length>240)return Empty("此连接方式无法安全匹配原版截图。");string root=Path.Combine(e.User,"Saves","Multiplayer"),path=Path.Combine(root,name);LauncherMaintenance.NoReparse(path);if(!Directory.Exists(path))return Empty("该服务器角色尚无最后下线截图；不使用其他角色图片。");return Read(path);}
}}
